insert into milestones (key, title, description, milestone_type, requirement_metric, requirement_count, icon_key) values
  ('first-step', 'First Step', 'You completed your first quest — a small step, and a true beginning.', 'first_step', 'quest_completions', 1, 'path'),
  ('first-prayer', 'A Prayer Begun', 'You wrote your first prayer, honest words offered in quiet.', 'first_step', 'prayers_created', 1, 'candle'),
  ('first-reflection', 'A Moment Noticed', 'You paused long enough to notice something, and wrote your first reflection.', 'first_step', 'reflections_created', 1, 'leaf'),
  ('first-answered-prayer', 'An Answer Came', 'You marked a prayer answered, and took a moment to receive it with gratitude.', 'first_step', 'prayers_answered', 1, 'bird'),
  ('first-chapter', 'The First Page', 'You opened the Scriptures and read your first chapter, at your own pace.', 'first_step', 'chapters_read', 1, 'book'),
  ('first-bookmark', 'A Verse to Carry', 'You kept your first verse, words to carry with you into the day.', 'first_step', 'verses_bookmarked', 1, 'bookmark'),
  ('seven-mornings', 'Seven Mornings', 'You returned on seven mornings, and a quiet rhythm began.', 'rhythm', 'journey_days', 7, 'sun'),
  ('month-of-mornings', 'A Month of Mornings', 'You returned for thirty days in all, one gentle morning at a time.', 'rhythm', 'journey_days', 30, 'sun'),
  ('steady-steps', 'Steady Steps', 'You completed ten quests, one steady step after another.', 'rhythm', 'quest_completions', 10, 'path'),
  ('into-the-story', 'Into the Story', 'You read ten chapters, letting Scripture unfold at its own pace.', 'scripture', 'chapters_read', 10, 'book'),
  ('deep-roots', 'Deep Roots', 'You wrote twenty reflections, and something in you grew quietly deeper.', 'depth', 'reflections_created', 20, 'tree'),
  ('practice-of-prayer', 'A Practice of Prayer', 'You brought ten prayers into words, learning the shape of honest conversation with God.', 'prayer', 'prayers_created', 10, 'candle'),
  ('words-for-the-road', 'Words for the Road', 'You gathered ten verses along the way, each one worth returning to.', 'scripture', 'verses_bookmarked', 10, 'bookmark'),
  ('gathered-graces', 'Gathered Graces', 'You noticed five answered prayers, and paused to give thanks for each one.', 'prayer', 'prayers_answered', 5, 'star'),
  ('kept-vigil', 'Kept Vigil', 'You returned to prayer through five quests, keeping quiet watch.', 'prayer', 'quests_prayer', 5, 'lantern'),
  ('by-lamplight', 'By Lamplight', 'You walked with Scripture through seven quests, a lamp for each step of the path.', 'scripture', 'quests_scripture', 7, 'lantern'),
  ('encourager', 'Encourager', 'You practiced kindness through five quests, leaving people a little lighter than you found them.', 'kindness', 'quests_kindness', 5, 'flower'),
  ('quiet-strength', 'Quiet Strength', 'You served others three times, quietly, without needing anyone to see.', 'kindness', 'quests_service', 3, 'tree'),
  ('counted-gifts', 'Counted Gifts', 'You paused to give thanks seven times, counting gifts easily missed.', 'rhythm', 'quests_gratitude', 7, 'star'),
  ('still-waters', 'Still Waters', 'You sat in stillness three times, and let the quiet do its slow work.', 'depth', 'quests_silence', 3, 'leaf'),
  ('around-the-table', 'Around the Table', 'You shared the journey with your family three times, faith practiced close to home.', 'kindness', 'quests_family', 3, 'flower'),
  ('fellow-travelers', 'Fellow Travelers', 'You walked with your community three times, and found the road kinder for the company.', 'kindness', 'quests_community', 3, 'chapel')
insert into prayer_prompts (key, text, category) values
  ('p01', 'Father, thank you for this morning. Walk with me through whatever it holds.', 'morning'),
  ('p02', 'Lord, before the day gets loud, let me begin it with you.', 'morning'),
  ('p03', 'God, I don''t know what today will bring. Help me take it one step at a time, with you.', 'morning'),
  ('p04', 'Father, the day is done. Help me set it down and rest in you.', 'evening'),
  ('p05', 'Lord, thank you for carrying me through today, even the parts I barely noticed.', 'evening'),
  ('p06', 'Jesus, quiet my mind tonight. Let me end this day grateful instead of restless.', 'evening'),
  ('p07', 'God, open my eyes to the ordinary gifts I walk past every day.', 'gratitude'),
  ('p08', 'Father, thank you for the small mercies of today, the ones I noticed and the ones I missed.', 'gratitude'),
  ('p09', 'Lord, teach me a gratitude that lasts longer than the moment.', 'gratitude'),
  ('p10', 'God, this is hard and I don''t understand it. Stay close to me anyway.', 'difficulty'),
  ('p11', 'Lord, I''m tired. Give me enough strength for today, and help me trust you with tomorrow.', 'difficulty'),
  ('p12', 'Father, I can''t see the way through this. Help me take the next step.', 'difficulty'),
  ('p13', 'Lord, be near the person I''m worried about tonight. Hold them when I can''t.', 'intercession'),
  ('p14', 'Father, I bring you my friend who is hurting. Give them what I don''t know how to give.', 'intercession'),
  ('p15', 'God, comfort the people who feel forgotten today, and help me notice the ones close to me.', 'intercession'),
  ('p16', 'Lord, slow me down. Teach me to sit quietly with you.', 'stillness'),
  ('p17', 'Father, quiet the noise in me. I want to listen more than I speak.', 'stillness'),
  ('p18', 'Jesus, I am always hurrying somewhere. Help me stop long enough to notice you here.', 'stillness'),
  ('p19', 'Father, I''m holding on to an old hurt. Help me loosen my grip and let mercy in.', 'forgiveness'),
  ('p20', 'God, forgive me for the ways I hurt people today, even the ways I didn''t see.', 'forgiveness'),
  ('p21', 'Jesus, forgiving this person feels beyond me. Begin it in me anyway.', 'forgiveness'),
  ('p22', 'Lord, give me courage for the conversation I''ve been avoiding, and the wisdom to know whether and when the time is right.', 'courage'),
  ('p23', 'God, help me do the right thing today, even when it''s the quiet, unnoticed thing.', 'courage'),
  ('p24', 'Father, I''m afraid. Remind me that you go with me.', 'courage'),
  ('p25', 'Lord, give me patience with the people closest to me, the ones who see me at my worst.', 'family'),
  ('p26', 'Father, bless my family today, especially the one I''ve been finding hard to love.', 'family'),
  ('p27', 'Jesus, help me really listen at home tonight, instead of just waiting to speak.', 'family'),
  ('p28', 'Lord, help me do today''s work honestly and well, and then let it go.', 'work'),
  ('p29', 'God, give me kindness for the people I work with, especially when the day runs long.', 'work'),
  ('p30', 'Father, when my work feels small or unseen, remind me that it still matters to you.', 'work'),
  ('p31', 'Jesus, make me quicker to be kind today than to be right.', 'general'),
  ('p32', 'God, I don''t have the words right now. Meet me here anyway.', 'general')
insert into reflection_prompts (key, text, context) values
  ('r01', 'What is one thing from today''s quest you''d like to carry with you?', 'after_quest'),
  ('r02', 'Was there a moment in this quest that slowed you down, in a good way?', 'after_quest'),
  ('r03', 'What surprised you as you walked through this step?', 'after_quest'),
  ('r04', 'If you shared one thing from today''s quest with a friend, what would it be?', 'after_quest'),
  ('r05', 'Which word or phrase stayed with you after the reading ended?', 'after_scripture'),
  ('r06', 'Where does this passage meet something you''re living right now?', 'after_scripture'),
  ('r07', 'If you could sit with the writer of these verses, what would you ask?', 'after_scripture'),
  ('r08', 'What part of this passage would you like to return to tomorrow?', 'after_scripture'),
  ('r09', 'What did you notice in the quiet, before or after the words?', 'after_prayer'),
  ('r10', 'Is there something you didn''t say in prayer that you''d like to name here?', 'after_prayer'),
  ('r11', 'How do you feel now, compared to when you began to pray?', 'after_prayer'),
  ('r12', 'What are you leaving in God''s hands as you go?', 'after_prayer'),
  ('r13', 'What would it look like to move through today a little more gently?', 'morning'),
  ('r14', 'Who might need your patience today?', 'morning'),
  ('r15', 'What small kindness could you carry into the hours ahead?', 'morning'),
  ('r16', 'As the day begins, what do you hope to remember by evening?', 'morning'),
  ('r17', 'Looking back, where did today feel most alive?', 'evening'),
  ('r18', 'What moment from today deserves a second look before you rest?', 'evening'),
  ('r19', 'What small mercy almost went unnoticed today?', 'evening'),
  ('r20', 'What can you set down before you sleep?', 'evening'),
  ('r21', 'What is something ordinary you would miss if it were gone?', 'gratitude'),
  ('r22', 'Who has been kind to you lately, in ways big or small?', 'gratitude'),
  ('r23', 'What good thing came to you today that you didn''t ask for?', 'gratitude'),
  ('r24', 'When did you last feel simply glad — and what was happening?', 'gratitude'),
  ('r25', 'What feels heavy to carry right now?', 'difficulty'),
  ('r26', 'If your worry could speak plainly, what would it say?', 'difficulty'),
  ('r27', 'What kind of help would actually help today?', 'difficulty'),
  ('r28', 'Where do you need mercy right now — from God, from others, or from yourself?', 'difficulty'),
  ('r29', 'What are you noticing about yourself in this season?', 'general'),
  ('r30', 'What question have you been living with lately?', 'general'),
  ('r31', 'What would real rest look like for you this week?', 'general'),
  ('r32', 'What would you like to begin again?', 'general')
insert into daily_verses (reference, book_slug, chapter, verse_start, verse_end, text, theme) values
  ('John 3:16', 'john', 3, 16, 16, 'For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life.', 'love'),
  ('Psalm 23:1-3', 'psalms', 23, 1, 3, 'Yahweh is my shepherd: I shall lack nothing. He makes me lie down in green pastures. He leads me beside still waters. He restores my soul. He guides me in the paths of righteousness for his name’s sake.', 'rest'),
  ('Psalm 46:10', 'psalms', 46, 10, 10, '“Be still, and know that I am God. I will be exalted among the nations. I will be exalted in the earth.”', 'stillness'),
  ('Isaiah 40:31', 'isaiah', 40, 31, 31, 'but those who wait for Yahweh will renew their strength. They will mount up with wings like eagles. They will run, and not be weary. They will walk, and not faint.', 'renewal'),
  ('Isaiah 41:10', 'isaiah', 41, 10, 10, 'Don’t you be afraid, for I am with you. Don’t be dismayed, for I am your God. I will strengthen you. Yes, I will help you. Yes, I will uphold you with the right hand of my righteousness.', 'courage'),
  ('Isaiah 26:3', 'isaiah', 26, 3, 3, 'You will keep whoever’s mind is steadfast in perfect peace, because he trusts in you.', 'peace'),
  ('Jeremiah 29:11', 'jeremiah', 29, 11, 11, 'For I know the thoughts that I think toward you,” says Yahweh, “thoughts of peace, and not of evil, to give you hope and a future.', 'hope'),
  ('Matthew 5:14-16', 'matthew', 5, 14, 16, 'You are the light of the world. A city located on a hill can’t be hidden. Neither do you light a lamp, and put it under a measuring basket, but on a stand; and it shines to all who are in the house. Even so, let your light shine before men; that they may see your good works, and glorify your Father who is in heaven.', 'kindness'),
  ('Matthew 6:33-34', 'matthew', 6, 33, 34, 'But seek first God’s Kingdom, and his righteousness; and all these things will be given to you as well. Therefore don’t be anxious for tomorrow, for tomorrow will be anxious for itself. Each day’s own evil is sufficient.', 'trust'),
  ('Matthew 11:28-30', 'matthew', 11, 28, 30, '“Come to me, all you who labor and are heavily burdened, and I will give you rest. Take my yoke upon you, and learn from me, for I am gentle and humble in heart; and you will find rest for your souls. For my yoke is easy, and my burden is light.”', 'rest'),
  ('Matthew 22:37-39', 'matthew', 22, 37, 39, 'Jesus said to him, “ ‘You shall love the Lord your God with all your heart, with all your soul, and with all your mind.’ This is the first and great commandment. A second likewise is this, ‘You shall love your neighbor as yourself.’', 'love'),
  ('Matthew 7:7-8', 'matthew', 7, 7, 8, '“Ask, and it will be given you. Seek, and you will find. Knock, and it will be opened for you. For everyone who asks receives. He who seeks finds. To him who knocks it will be opened.', 'prayer'),
  ('Philippians 4:6-7', 'philippians', 4, 6, 7, 'In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God. And the peace of God, which surpasses all understanding, will guard your hearts and your thoughts in Christ Jesus.', 'peace'),
  ('Philippians 4:13', 'philippians', 4, 13, 13, 'I can do all things through Christ, who strengthens me.', 'courage'),
  ('Romans 8:28', 'romans', 8, 28, 28, 'We know that all things work together for good for those who love God, for those who are called according to his purpose.', 'trust'),
  ('Romans 8:38-39', 'romans', 8, 38, 39, 'For I am persuaded that neither death, nor life, nor angels, nor principalities, nor things present, nor things to come, nor powers, nor height, nor depth, nor any other created thing will be able to separate us from God’s love which is in Christ Jesus our Lord.', 'love'),
  ('Romans 12:12', 'romans', 12, 12, 12, 'rejoicing in hope; enduring in troubles; continuing steadfastly in prayer;', 'hope'),
  ('Romans 15:13', 'romans', 15, 13, 13, 'Now may the God of hope fill you with all joy and peace in believing, that you may abound in hope, in the power of the Holy Spirit.', 'hope'),
  ('Joshua 1:9', 'joshua', 1, 9, 9, 'Haven’t I commanded you? Be strong and courageous. Don’t be afraid. Don’t be dismayed, for Yahweh your God is with you wherever you go.”', 'courage'),
  ('Proverbs 3:5-6', 'proverbs', 3, 5, 6, 'Trust in Yahweh with all your heart, and don’t lean on your own understanding. In all your ways acknowledge him, and he will make your paths straight.', 'trust'),
  ('Proverbs 16:3', 'proverbs', 16, 3, 3, 'Commit your deeds to Yahweh, and your plans shall succeed.', 'work'),
  ('Psalm 118:24', 'psalms', 118, 24, 24, 'This is the day that Yahweh has made. We will rejoice and be glad in it!', 'gratitude'),
  ('Psalm 121:1-2', 'psalms', 121, 1, 2, 'I will lift up my eyes to the hills. Where does my help come from? My help comes from Yahweh, who made heaven and earth.', 'trust'),
  ('Psalm 139:23-24', 'psalms', 139, 23, 24, 'Search me, God, and know my heart. Try me, and know my thoughts. See if there is any wicked way in me, and lead me in the everlasting way.', 'honesty'),
  ('Lamentations 3:22-23', 'lamentations', 3, 22, 23, 'It is because of Yahweh’s loving kindnesses that we are not consumed, because his compassion doesn’t fail. They are new every morning. Great is your faithfulness.', 'renewal'),
  ('Micah 6:8', 'micah', 6, 8, 8, 'He has shown you, O man, what is good. What does Yahweh require of you, but to act justly, to love mercy, and to walk humbly with your God?', 'justice'),
  ('Zephaniah 3:17', 'zephaniah', 3, 17, 17, 'Yahweh, your God, is among you, a mighty one who will save. He will rejoice over you with joy. He will calm you in his love. He will rejoice over you with singing.', 'love'),
  ('Galatians 5:22-23', 'galatians', 5, 22, 23, 'But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faith, gentleness, and self-control. Against such things there is no law.', 'growth'),
  ('Galatians 6:9', 'galatians', 6, 9, 9, 'Let’s not be weary in doing good, for we will reap in due season, if we don’t give up.', 'perseverance'),
  ('Ephesians 2:8-10', 'ephesians', 2, 8, 10, 'for by grace you have been saved through faith, and that not of yourselves; it is the gift of God, not of works, that no one would boast. For we are his workmanship, created in Christ Jesus for good works, which God prepared before that we would walk in them.', 'grace'),
  ('Ephesians 4:32', 'ephesians', 4, 32, 32, 'And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.', 'forgiveness'),
  ('Colossians 3:12', 'colossians', 3, 12, 12, 'Put on therefore, as God’s chosen ones, holy and beloved, a heart of compassion, kindness, lowliness, humility, and perseverance;', 'kindness'),
  ('Colossians 3:23', 'colossians', 3, 23, 23, 'And whatever you do, work heartily, as for the Lord, and not for men,', 'work'),
  ('1 Thessalonians 5:11', '1-thessalonians', 5, 11, 11, 'Therefore exhort one another, and build each other up, even as you also do.', 'encouragement'),
  ('1 Thessalonians 5:16-18', '1-thessalonians', 5, 16, 18, 'Always rejoice. Pray without ceasing. In everything give thanks, for this is the will of God in Christ Jesus toward you.', 'gratitude'),
  ('Hebrews 10:24-25', 'hebrews', 10, 24, 25, 'Let’s consider how to provoke one another to love and good works, not forsaking our own assembling together, as the custom of some is, but exhorting one another, and so much the more as you see the Day approaching.', 'community'),
  ('Hebrews 11:1', 'hebrews', 11, 1, 1, 'Now faith is assurance of things hoped for, proof of things not seen.', 'faith'),
  ('James 1:19', 'james', 1, 19, 19, 'So, then, my beloved brothers, let every man be swift to hear, slow to speak, and slow to anger;', 'patience'),
  ('James 1:22', 'james', 1, 22, 22, 'But be doers of the word, and not only hearers, deluding your own selves.', 'action'),
  ('James 4:8', 'james', 4, 8, 8, 'Draw near to God, and he will draw near to you. Cleanse your hands, you sinners. Purify your hearts, you double-minded.', 'prayer'),
  ('1 Peter 5:7', '1-peter', 5, 7, 7, 'casting all your worries on him, because he cares for you.', 'rest'),
  ('1 John 4:7', '1-john', 4, 7, 7, 'Beloved, let’s love one another, for love is of God; and everyone who loves has been born of God, and knows God.', 'love'),
  ('1 John 4:19', '1-john', 4, 19, 19, 'We love him, because he first loved us.', 'love'),
  ('Psalm 27:1', 'psalms', 27, 1, 1, 'Yahweh is my light and my salvation. Whom shall I fear? Yahweh is the strength of my life. Of whom shall I be afraid?', 'courage'),
  ('Psalm 34:8', 'psalms', 34, 8, 8, 'Oh taste and see that Yahweh is good. Blessed is the man who takes refuge in him.', 'gratitude'),
  ('Psalm 51:10', 'psalms', 51, 10, 10, 'Create in me a clean heart, O God. Renew a right spirit within me.', 'renewal'),
  ('Psalm 90:12', 'psalms', 90, 12, 12, 'So teach us to count our days, that we may gain a heart of wisdom.', 'wisdom'),
  ('Psalm 103:2-4', 'psalms', 103, 2, 4, 'Praise Yahweh, my soul, and don’t forget all his benefits, who forgives all your sins, who heals all your diseases, who redeems your life from destruction, who crowns you with loving kindness and tender mercies,', 'gratitude'),
  ('Psalm 19:14', 'psalms', 19, 14, 14, 'Let the words of my mouth and the meditation of my heart be acceptable in your sight, Yahweh, my rock, and my redeemer.', 'prayer'),
  ('Mark 12:30-31', 'mark', 12, 30, 31, 'you shall love the Lord your God with all your heart, and with all your soul, and with all your mind, and with all your strength.’ This is the first commandment. The second is like this, ‘You shall love your neighbor as yourself.’ There is no other commandment greater than these.”', 'love'),
  ('Luke 6:31', 'luke', 6, 31, 31, '“As you would like people to do to you, do exactly so to them.', 'kindness'),
  ('Luke 12:34', 'luke', 12, 34, 34, 'For where your treasure is, there will your heart be also.', 'treasure'),
  ('John 1:5', 'john', 1, 5, 5, 'The light shines in the darkness, and the darkness hasn’t overcome it.', 'hope'),
  ('John 13:34-35', 'john', 13, 34, 35, 'A new commandment I give to you, that you love one another. Just as I have loved you, you also love one another. By this everyone will know that you are my disciples, if you have love for one another.”', 'love'),
  ('John 14:27', 'john', 14, 27, 27, 'Peace I leave with you. My peace I give to you; not as the world gives, I give to you. Don’t let your heart be troubled, neither let it be fearful.', 'peace'),
  ('John 15:5', 'john', 15, 5, 5, 'I am the vine. You are the branches. He who remains in me and I in him bears much fruit, for apart from me you can do nothing.', 'growth'),
  ('1 Corinthians 13:4-7', '1-corinthians', 13, 4, 7, 'Love is patient and is kind. Love doesn’t envy. Love doesn’t brag, is not proud, doesn’t behave itself inappropriately, doesn’t seek its own way, is not provoked, takes no account of evil; doesn’t rejoice in unrighteousness, but rejoices with the truth; bears all things, believes all things, hopes all things, and endures all things.', 'love'),
  ('1 Corinthians 16:14', '1-corinthians', 16, 14, 14, 'Let all that you do be done in love.', 'love'),
  ('2 Corinthians 5:17', '2-corinthians', 5, 17, 17, 'Therefore if anyone is in Christ, he is a new creation. The old things have passed away. Behold, all things have become new.', 'renewal'),
  ('Deuteronomy 31:8', 'deuteronomy', 31, 8, 8, 'Yahweh himself is who goes before you. He will be with you. He will not fail you nor forsake you. Don’t be afraid. Don’t be discouraged.”', 'courage')
insert into quest_templates (faith_provider_id, slug, title, category, duration_minutes, difficulty, energy_level, solo_or_social, indoor_or_outdoor, invitation, why_it_matters, scripture_reference, scripture_text_snapshot, reflection_prompt, prayer_prompt, growth_type, tags, season_tags, tradition_tags, sensitivity_tags, is_premium)
